import java.util.*;
class Box<T>{private final T value;Box(T value){this.value=value;}T get(){return value;}}
public class Main {public static void main(String[] args){Scanner s=new Scanner(System.in);Box<String> text=new Box<>(s.next());Box<Integer> number=new Box<>(s.nextInt());System.out.println("text="+text.get()+" number="+number.get());}}

