import java.util.*;
class Counter{private int value;class Step{void add(int n){value+=n;}}int value(){return value;}}
public class Main {public static void main(String[] args){Scanner s=new Scanner(System.in);Counter c=new Counter();Counter.Step step=c.new Step();step.add(s.nextInt());step.add(s.nextInt());System.out.println(c.value());}}
